const pair=(es,en)=>({es,en});
export const tracks=[
{id:'mechanics',name:pair('Mecánica','Mechanics'),intro:pair('De fuerza y energía a un diagnóstico sustentado.','From force and energy to evidence-based diagnosis.'),lab:'engine',lessons:[]},
{id:'electronics',name:pair('Electricidad y electrónica','Electricity & electronics'),intro:pair('Lee circuitos, ondas y señales antes de cambiar componentes.','Read circuits, waveforms and signals before replacing parts.'),lab:'signal',lessons:[]},
{id:'hydraulics',name:pair('Hidráulica','Hydraulics'),intro:pair('Relaciona presión, caudal, fuerza y pérdidas.','Connect pressure, flow, force and losses.'),lab:'hydraulic',lessons:[]},
{id:'pneumatics',name:pair('Neumática','Pneumatics'),intro:pair('Sigue el aire desde el compresor hasta el escape.','Follow the air from the compressor to the exhaust.'),lab:'pneumatic',lessons:[]}
];
function lesson(track,id,title,goal,body,formula,example,practice,mistake,question,answers,correct,feedback,lab){tracks.find(t=>t.id===track).lessons.push({id,title,goal,body,formula,example,practice,mistake,question,answers,correct,feedback,lab});}
lesson('mechanics','torque',pair('01 · Fuerza, torque y potencia','01 · Force, torque and power'),pair('Distinguir esfuerzo, giro y rapidez de transferencia de energía.','Distinguish force, turning effect and rate of energy transfer.'),pair('La fuerza neta cambia el movimiento; el torque describe su efecto de giro alrededor de un eje. Importa la distancia perpendicular a la línea de acción, no solo la longitud de la herramienta. La potencia combina torque y velocidad angular: tener más torque no significa producir más potencia a cualquier velocidad.','Net force changes motion; torque describes its turning effect about an axis. The perpendicular distance to the force line matters, not just tool length. Power combines torque and angular speed: greater torque does not imply greater power at every speed.'),'τ = F·r⊥; P = τ·ω; ω = 2π·rpm/60',pair('Una fuerza perpendicular de 100 N a 0,25 m produce 25 N·m. A 1 200 rpm, 25 N·m equivalen a 25 × 125,66 = 3 142 W. La primera operación calcula torque; la segunda, potencia.','A perpendicular 100 N force at 0.25 m produces 25 N·m. At 1,200 rpm, 25 N·m corresponds to 25 × 125.66 = 3,142 W. The first operation finds torque; the second finds power.'),pair('Pausa el motor y avanza el ciclo. Localiza dónde la biela aplica fuerza al cigüeñal. Cerca del punto muerto, la geometría reduce el brazo de giro.','Pause the engine and scrub the cycle. Locate where the connecting rod loads the crankshaft. Near dead centre, geometry reduces the turning lever arm.'),pair('Confundir N·m de torque con joules de trabajo: comparten dimensiones, pero describen magnitudes distintas.','Confusing N·m of torque with joules of work: they share dimensions but describe different quantities.'),pair('A igual fuerza perpendicular, duplicar el brazo produce…','At the same perpendicular force, doubling the lever arm produces…'),[pair('El doble de torque','Twice the torque'),pair('La mitad de torque','Half the torque'),pair('La misma potencia siempre','Always the same power')],0,pair('τ es proporcional al brazo. La potencia también necesita la velocidad angular.','Torque is proportional to the lever arm. Power additionally requires angular speed.'));
lesson('mechanics','fourstroke',pair('02 · Motor de cuatro tiempos','02 · The four-stroke engine'),pair('Relacionar válvulas, pistón y combustión en 720°.','Relate valves, piston and combustion over 720°.'),pair('Admisión: entra carga mientras baja el pistón. Compresión: las válvulas están cerradas y el pistón sube. Expansión: los gases de la combustión realizan trabajo. Escape: se expulsan gases al subir. El cigüeñal completa dos vueltas por ciclo; el árbol de levas, una. El motor real abre y cierra válvulas con adelantos y retrasos que este modelo ideal no representa.','Intake: charge enters while the piston descends. Compression: valves are closed as the piston rises. Expansion: combustion gases perform work. Exhaust: gases leave as the piston rises. The crankshaft turns twice per cycle; the camshaft once. Real valve timing includes advance and overlap that this ideal model does not represent.'),'1 ciclo / cycle = 720°',pair('A 1 200 rpm hay 20 vueltas de cigüeñal por segundo: 10 ciclos por segundo en cada cilindro de cuatro tiempos. No son 20 combustiones por cilindro.','At 1,200 rpm the crankshaft turns 20 times per second: 10 cycles per second in each four-stroke cylinder. That is not 20 combustion events per cylinder.'),pair('Recorre 0–180–360–540–720°. Predice qué válvula estará abierta antes de mover el cursor.','Scrub through 0–180–360–540–720°. Predict which valve will be open before moving the cursor.'),pair('La chispa inicia la combustión; no aporta la mayor parte de la energía del motor.','The spark initiates combustion; it does not provide most of the engine’s energy.'),pair('¿Cuántas vueltas de cigüeñal tiene un ciclo?','How many crankshaft revolutions make one cycle?'),[pair('Una','One'),pair('Dos','Two'),pair('Cuatro','Four')],1,pair('Cuatro carreras de 180° suman 720°, dos vueltas.','Four 180° strokes add up to 720°, or two revolutions.'));
lesson('mechanics','transmission',pair('03 · Transmisión y rendimiento','03 · Transmission and efficiency'),pair('Calcular qué se gana y qué se pierde al reducir velocidad.','Calculate what changes when gearing reduces speed.'),pair('Un engranaje conductor pequeño mueve uno grande más lentamente. Idealmente se conserva la potencia; el torque aumenta a cambio de velocidad. En una transmisión real, la fricción y la agitación del lubricante disipan energía. La eficiencia se aplica a la potencia transmitida, no se suma a la relación de dientes.','A small driving gear turns a larger gear more slowly. Ideally power is conserved; torque increases in exchange for speed. In a real transmission, friction and lubricant churning dissipate energy. Efficiency applies to transmitted power; it is not added to the tooth ratio.'),'n₂ = n₁·Z₁/Z₂; τ₂ = τ₁·(Z₂/Z₁)·η',pair('Un piñón de 20 dientes impulsa uno de 60. Con 900 rpm, 10 N·m y η = 0,90: salida 300 rpm y 27 N·m. Los 3 N·m que faltan frente al caso ideal reflejan pérdidas a esa velocidad.','A 20-tooth gear drives a 60-tooth gear. With 900 rpm, 10 N·m and η = 0.90, output is 300 rpm and 27 N·m. The 3 N·m difference from the ideal case represents losses at that speed.'),pair('En el banco identifica el cigüeñal como entrada posible de una transmisión. Calcula primero la reducción; el modelo del motor no incluye una caja de cambios.','Identify the crankshaft as a possible transmission input. Calculate the reduction first; the engine model does not include a gearbox.'),pair('Una reducción no multiplica la energía disponible.','A reduction does not multiply available energy.'),pair('Una reducción ideal 3:1 entrega…','An ideal 3:1 reduction delivers…'),[pair('Tres veces velocidad','Three times the speed'),pair('Un tercio de velocidad y triple torque','One third the speed and triple torque'),pair('Triple potencia','Triple power')],1,pair('La potencia ideal de entrada y salida coincide.','Ideal input and output power are equal.'));
lesson('mechanics','thermal',pair('04 · Lubricación y temperatura','04 · Lubrication and temperature'),pair('Separar síntomas de calentamiento de sus posibles causas.','Separate overheating symptoms from possible causes.'),pair('El aceite forma películas que reducen contacto entre superficies y transporta calor. El refrigerante lleva calor del motor al radiador. Un indicador de presión no mide directamente la calidad de lubricación de cada cojinete. La temperatura depende del calor generado y del que se evacua: nivel, circulación, intercambio y carga deben evaluarse como sistema.','Oil forms films that reduce surface contact and carries heat. Coolant moves heat from the engine to the radiator. A pressure indicator does not directly measure lubrication quality at every bearing. Temperature depends on generated and rejected heat: level, circulation, heat exchange and load must be evaluated as a system.'),'ΔE = E entrada / in − E salida / out',pair('Si entran 12 kJ/s de calor y solo salen 9 kJ/s, el sistema acumula 3 kJ/s. Una temperatura creciente no identifica por sí sola una bomba averiada.','If 12 kJ/s of heat enters and only 9 kJ/s leaves, the system accumulates 3 kJ/s. Rising temperature alone does not identify a failed pump.'),pair('Señala cilindro y pistón. Explica qué superficies necesitan lubricación y por qué el corte 3D no permite medir presión de aceite ni temperatura real.','Identify cylinder and piston. Explain which surfaces need lubrication and why the 3D cutaway cannot measure actual oil pressure or temperature.'),pair('Abrir un circuito caliente presurizado es peligroso. Las inspecciones reales requieren enfriamiento y procedimiento del fabricante.','Opening a hot pressurised circuit is hazardous. Real inspection requires cooling and the manufacturer’s procedure.'),pair('Una temperatura alta demuestra…','A high temperature proves…'),[pair('Que la bomba está rota','That the pump is broken'),pair('Un desequilibrio térmico; falta localizar la causa','A heat imbalance; the cause still needs locating'),pair('Que siempre falta aceite','That oil is always low')],1,pair('Un síntoma dirige las pruebas; no reemplaza el diagnóstico.','A symptom guides tests; it does not replace diagnosis.'));
lesson('mechanics','nostart',pair('05 · Diagnosticar «no arranca»','05 · Diagnose a no-start'),pair('Elegir pruebas según si el motor gira, gira lento o gira normal.','Choose tests according to no crank, slow crank or normal cranking.'),pair('Primero clasifica el síntoma. Sin giro: comprueba suministro y mando. Giro lento: mide batería bajo carga y caídas de tensión. Giro normal sin arrancar: examina encendido, combustible y compresión con equipo adecuado. Una lectura en reposo puede parecer correcta y caer bajo carga. Registra condición, unidad, referencia y conclusión antes de sustituir una pieza.','First classify the symptom. No crank: check supply and control. Slow crank: measure battery under load and voltage drops. Normal cranking without starting: examine ignition, fuel and compression using suitable equipment. An unloaded reading can look normal yet collapse under load. Record conditions, units, reference and conclusion before replacing a part.'),'V carga / load = V fuente / source − ΣΔV',pair('Banco didáctico: 12,6 V en reposo y 7,8 V al intentar arrancar apuntan a un problema de suministro bajo carga. Una caída de 2,8 V en una conexión requiere localizar resistencia excesiva. Son valores del simulador, no límites universales.','Teaching bench: 12.6 V at rest and 7.8 V during cranking point to a supply problem under load. A 2.8 V drop across a connection calls for locating excessive resistance. These are simulator values, not universal limits.'),pair('Compara las cuatro fases del motor. Explica por qué ver girar el pistón no demuestra que haya chispa, combustible o sellado suficiente.','Compare the four engine phases. Explain why seeing the piston move does not prove spark, fuel or sufficient sealing.'),pair('Medir compresión sin giro o carga del alternador con el motor detenido no produce una prueba válida de esos sistemas.','Testing compression without cranking or alternator charging with the engine stopped does not provide a valid test of those systems.'),pair('Con giro lento, ¿qué prueba aporta evidencia primero?','With slow cranking, which test provides useful initial evidence?'),[pair('Batería bajo carga','Battery under load'),pair('Cambiar bujías','Replace spark plugs'),pair('Cambiar inyectores','Replace injectors')],0,pair('Primero verifica la energía para girar. Después separa batería y conexiones con mediciones bajo carga.','First verify the energy needed to crank. Then distinguish battery and connections using loaded measurements.'));
lesson('electronics','ohm',pair('01 · Tensión, corriente y potencia','01 · Voltage, current and power'),pair('Calcular corriente y disipación sin confundir sus unidades.','Calculate current and dissipation without confusing units.'),pair('La tensión es energía por carga entre dos puntos; la corriente es carga por tiempo a través de una sección. En una resistencia óhmica, V = IR. Un voltímetro se conecta entre dos puntos; medir corriente requiere una técnica distinta. El simulador usa circuitos ideales de baja tensión, sin instrucciones de conexión a red.','Voltage is energy per charge between two points; current is charge per time through a cross-section. In an ohmic resistor, V = IR. A voltmeter connects between two points; measuring current requires a different technique. The simulator uses ideal low-voltage circuits and gives no mains wiring procedure.'),'I = V/R; P = VI',pair('12 V sobre 1 kΩ: I = 12/1 000 = 0,012 A = 12 mA. P = 12 × 0,012 = 0,144 W. La potencia nominal del componente debe elegirse con margen y condiciones térmicas.','12 V across 1 kΩ: I = 12/1,000 = 0.012 A = 12 mA. P = 12 × 0.012 = 0.144 W. Component power rating needs margin and thermal conditions considered.'),pair('En el banco DC cambia resistencia manteniendo tensión. Predice corriente y potencia antes de leerlas.','In the DC bench change resistance at fixed voltage. Predict current and power before reading them.'),pair('No conectes un amperímetro directamente entre los bornes de una fuente como si fuera un voltímetro.','Do not connect an ammeter directly across a source as if it were a voltmeter.'),pair('Duplicar R con V fija hace que I…','Doubling R at fixed V makes I…'),[pair('Se duplique','Double'),pair('Se reduzca a la mitad','Halve'),pair('No cambie','Stay unchanged')],1,pair('I = V/R; la potencia V²/R también se reduce a la mitad.','I = V/R; power V²/R also halves.'),'dc');
lesson('electronics','ac',pair('02 · Sinusoide y RMS','02 · Sine wave and RMS'),pair('Distinguir pico, periodo y valor eficaz.','Distinguish peak, period and effective value.'),pair('Una sinusoide alterna de signo; su promedio puede ser cero aunque entregue energía a una resistencia. RMS compara el calentamiento con una señal DC. La relación pico/√2 se aplica a una sinusoide, no a cualquier onda. La frecuencia cambia cuánto dura cada ciclo; no obliga a cambiar amplitud.','A sine wave changes sign; its average can be zero while delivering energy to a resistor. RMS compares heating with DC. Peak/√2 applies to a sine wave, not every waveform. Frequency changes cycle duration; it does not require amplitude to change.'),'v(t) = Vp sin(2πft); T = 1/f; Vrms = Vp/√2',pair('Vp = 10 V y f = 50 Hz: Vrms = 7,07 V y T = 20 ms. Sobre 100 Ω, P media = 7,07²/100 = 0,50 W.','Vp = 10 V and f = 50 Hz: Vrms = 7.07 V and T = 20 ms. Across 100 Ω, average P = 7.07²/100 = 0.50 W.'),pair('Duplica la frecuencia y conserva el pico. Observa cómo se comprime la onda en el eje temporal.','Double frequency while preserving peak. Observe the waveform compress along the time axis.'),pair('El valor promedio cero no significa potencia media cero.','Zero average voltage does not mean zero average power.'),pair('Si f pasa de 50 a 100 Hz, T pasa de…','If f changes from 50 to 100 Hz, T changes from…'),[pair('20 a 10 ms','20 to 10 ms'),pair('20 a 40 ms','20 to 40 ms'),pair('10 a 20 ms','10 to 20 ms')],0,pair('T = 1/f: el doble de frecuencia ocupa la mitad de tiempo por ciclo.','T = 1/f: twice the frequency takes half the time per cycle.'),'sine');
lesson('electronics','threephase',pair('03 · Trifásica: fase y línea','03 · Three-phase: phase and line'),pair('Entender por qué tres fases no son tres tensiones sumadas.','Understand why three phases are not three voltages added arithmetically.'),pair('Tres sinusoides equilibradas tienen igual amplitud y frecuencia, separadas 120°. En estrella, una carga está entre línea y punto común. La tensión entre líneas es una diferencia de ondas, no la suma de valores RMS. La corriente de neutro se anula en el caso equilibrado sinusoidal; cargas desiguales o armónicos cambian esa conclusión.','Three balanced sine waves have equal amplitude and frequency, separated by 120°. In star, a load lies between line and common point. Line-to-line voltage is a difference of waves, not a sum of RMS values. Neutral current cancels in the balanced sinusoidal case; unequal loads or harmonics change that conclusion.'),'VL = √3·Vfase (Y); φ = 0°, −120°, −240°',pair('Si cada fase tiene 10 V pico, Vf RMS = 7,07 V. Entre líneas hay √3 × 7,07 = 12,25 V RMS. La gráfica muestra tensiones de fase.','If each phase has 10 V peak, phase RMS is 7.07 V. Line-to-line voltage is √3 × 7.07 = 12.25 V RMS. The graph shows phase voltages.'),pair('Pausa las tres curvas y compara sus valores en el mismo instante. Su suma ideal es cero; ninguna tiene que ser cero individualmente.','Pause the three curves and compare values at the same instant. Their ideal sum is zero; none needs to be individually zero.'),pair('No apliques relaciones estrella/triángulo sin identificar qué tensión y corriente estás midiendo.','Do not apply star/delta relations without identifying which voltage and current you are measuring.'),pair('120° equivale a…','120° is…'),[pair('120 V','120 V'),pair('Un tercio de ciclo','One third of a cycle'),pair('Media vuelta','Half a turn')],1,pair('360° es un ciclo; el desfase no es una tensión.','360° is one cycle; phase displacement is not voltage.'),'threephase');
lesson('electronics','rectifier',pair('04 · Rectificar no es regular','04 · Rectifying is not regulating'),pair('Reconocer una salida pulsante y el papel del filtrado.','Recognise a pulsating output and the role of filtering.'),pair('Un puente rectificador conduce por pares de diodos y conserva una polaridad de salida. Sin filtro, la tensión sigue pulsando. Un condensador se carga cerca de los picos y entrega carga entre ellos; su rizado depende de corriente, capacidad y frecuencia. Un regulador es otra etapa y necesita margen de tensión y disipación.','A bridge rectifier conducts through diode pairs and maintains output polarity. Without filtering, voltage still pulsates. A capacitor charges near peaks and supplies charge between them; ripple depends on current, capacitance and frequency. A regulator is another stage and needs voltage headroom and thermal design.'),'f rizado / ripple = 2f; ΔV ≈ I/(2fC)',pair('A 50 Hz, I = 0,10 A y C = 1 000 µF, el rizado aproximado es 0,10/(100 × 0,001) = 1 V. Es una aproximación de descarga con rizado pequeño; no incluye las caídas de diodos.','At 50 Hz, I = 0.10 A and C = 1,000 µF, approximate ripple is 0.10/(100 × 0.001) = 1 V. This is a small-ripple discharge approximation; it excludes diode drops.'),pair('Compara la sinusoide de entrada y el valor absoluto de salida del puente ideal. Cuenta dos pulsos por ciclo.','Compare the input sine wave and the ideal bridge’s absolute-value output. Count two pulses per cycle.'),pair('La gráfica ideal sin filtro no representa una fuente DC regulada.','The ideal unfiltered graph does not represent a regulated DC supply.'),pair('Un puente ideal con entrada de 60 Hz pulsa a…','An ideal bridge with 60 Hz input pulsates at…'),[pair('30 Hz','30 Hz'),pair('60 Hz','60 Hz'),pair('120 Hz','120 Hz')],2,pair('Cada semiciclo produce un pulso positivo.','Each half-cycle produces a positive pulse.'),'rectifier');
lesson('electronics','opamp',pair('05 · Amplificación y saturación','05 · Amplification and saturation'),pair('Predecir cuándo la salida deja de seguir la ganancia.','Predict when output stops following the intended gain.'),pair('En un amplificador no inversor con realimentación negativa, la ganancia ideal es 1 + Rf/Rg. La alimentación entrega la energía de salida. La relación deja de ser válida al saturar o exceder límites de ancho de banda, velocidad o entrada. Este banco limita la salida a ±12 V para ilustrar recorte; un dispositivo real puede necesitar margen respecto de los rieles.','In a non-inverting amplifier with negative feedback, ideal gain is 1 + Rf/Rg. The supply provides output energy. The relation no longer holds when saturating or exceeding bandwidth, slew-rate or input limits. This bench clips at ±12 V to illustrate saturation; a real device may need headroom from its rails.'),'Av = 1 + Rf/Rg; Vout ideal = Av·Vin',pair('Rg = 10 kΩ y Rf = 40 kΩ: ganancia 5. Con 2 V pico se piden 10 V pico; con 3 V se piden 15 V y el modelo recorta a 12 V.','Rg = 10 kΩ and Rf = 40 kΩ give gain 5. A 2 V peak input requests 10 V peak; 3 V requests 15 V, and the model clips at 12 V.'),pair('Aumenta la ganancia y busca dónde se aplana la salida. Reduce la entrada para recuperar una onda sin recorte.','Increase gain and find where the output flattens. Reduce the input to recover an unclipped wave.'),pair('La ganancia no permite superar libremente la alimentación.','Gain does not allow output to exceed the supply freely.'),pair('Con Av = 5 y Vin = 3 V pico, la salida ideal pediría…','With Av = 5 and Vin = 3 V peak, ideal output would request…'),[pair('15 V pico; puede saturar','15 V peak; it may saturate'),pair('0,6 V','0.6 V'),pair('Siempre 5 V','Always 5 V')],0,pair('5 × 3 = 15 V supera el límite de 12 V del banco.','5 × 3 = 15 V exceeds this bench’s 12 V limit.'),'opamp');
lesson('hydraulics','pascal',pair('01 · Presión y fuerza','01 · Pressure and force'),pair('Convertir presión y área en fuerza, sin crear energía.','Convert pressure and area into force without creating energy.'),pair('En un líquido confinado en equilibrio, un incremento de presión se transmite por el fluido. Sobre un pistón, la fuerza depende de presión y área. En una prensa ideal con pistones a igual altura, la presión es común, pero sus fuerzas pueden ser distintas. La prensa intercambia recorrido por fuerza.','In a confined liquid at equilibrium, a pressure increase is transmitted through the fluid. On a piston, force depends on pressure and area. In an ideal press with pistons at equal elevation, pressure is shared but forces can differ. The press exchanges travel for force.'),'p = F/A; F₂/F₁ = A₂/A₁',pair('20 N sobre 2 cm²: 20/0,0002 = 100 000 Pa = 1 bar. Con salida de 8 cm², F₂ = 80 N. Si la entrada baja 40 mm, la salida sube 10 mm en el modelo ideal.','20 N over 2 cm² gives 20/0.0002 = 100,000 Pa = 1 bar. With an 8 cm² output, F₂ = 80 N. If the input descends 40 mm, the output rises 10 mm in the ideal model.'),pair('Aumenta la relación de áreas. Observa que la salida tiene más fuerza y menos recorrido por el mismo desplazamiento de entrada.','Increase area ratio. Observe that output gains force but loses travel for the same input displacement.'),pair('1 cm² = 0,0001 m², no 0,01 m².','1 cm² = 0.0001 m², not 0.01 m².'),pair('Si el área de salida es cuatro veces mayor, su fuerza ideal es…','If output area is four times larger, ideal output force is…'),[pair('Cuatro veces mayor','Four times larger'),pair('Igual','Equal'),pair('Cuatro veces menor','Four times smaller')],0,pair('La misma presión actúa sobre cuatro veces el área.','The same pressure acts over four times the area.'));
lesson('hydraulics','flow',pair('02 · Caudal y velocidad','02 · Flow and velocity'),pair('Separar la capacidad de empujar de la rapidez de avance.','Separate pushing capacity from travel speed.'),pair('El caudal es volumen por tiempo. En un cilindro ideal sin fuga, la velocidad es Q/A. La presión necesaria depende de la carga. Una bomba entrega caudal; la resistencia del circuito determina la presión requerida, limitada por la protección. El retorno de un cilindro de vástago simple usa un área anular menor.','Flow is volume per time. In an ideal cylinder without leakage, speed is Q/A. Required pressure depends on load. A pump supplies flow; circuit resistance determines required pressure, limited by protection. Retraction of a single-rod cylinder uses a smaller annular area.'),'v = Q/A; Q entrada / in = Q salida / out',pair('6 L/min = 0,0001 m³/s. Con A = 10 cm² = 0,001 m², v = 0,10 m/s. Duplicar el área a caudal constante reduce la velocidad a 0,05 m/s.','6 L/min = 0.0001 m³/s. With A = 10 cm² = 0.001 m², v = 0.10 m/s. Doubling area at constant flow reduces speed to 0.05 m/s.'),pair('En la prensa, compara los recorridos durante el mismo tiempo: el volumen desplazado debe coincidir a ambos lados.','In the press, compare travel over the same time: displaced volume must match on both sides.'),pair('Subir la presión no es una regulación universal de velocidad.','Increasing pressure is not a universal speed control.'),pair('A caudal constante, duplicar el área hace que la velocidad…','At constant flow, doubling area makes speed…'),[pair('Se duplique','Double'),pair('Se reduzca a la mitad','Halve'),pair('Sea cero','Become zero')],1,pair('v = Q/A. La misma cantidad de aceite llena una sección mayor más lentamente.','v = Q/A. The same oil volume fills a larger section more slowly.'));
lesson('hydraulics','power',pair('03 · Potencia hidráulica y calor','03 · Hydraulic power and heat'),pair('Cuantificar energía útil y pérdidas.','Quantify useful energy and losses.'),pair('La potencia hidráulica transferida depende de una diferencia de presión y del caudal que la atraviesa. Una caída en una restricción puede disipar esa potencia como calor en vez de mover una carga. La presión estática alta sin caudal no implica una gran potencia hidráulica transferida por ese punto.','Transferred hydraulic power depends on pressure difference and flow through it. A pressure drop across a restriction can dissipate that power as heat rather than moving a load. High static pressure with no flow does not imply large hydraulic power transfer through that point.'),'P = Δp·Q; P[kW] = Δp[bar]·Q[L/min]/600',pair('60 bar y 12 L/min representan 1,2 kW. Si el actuador entrega 0,9 kW útiles, el rendimiento global considerado es 75 % y se pierden 0,3 kW.','60 bar and 12 L/min represent 1.2 kW. If the actuator delivers 0.9 kW useful output, the considered overall efficiency is 75%, with 0.3 kW lost.'),pair('Calcula el trabajo de ambos pistones de la prensa: fuerza por recorrido. Debe ser igual en este modelo sin pérdidas.','Calculate work at each press piston: force times travel. It should match in this lossless model.'),pair('Más presión no significa mejor rendimiento.','More pressure does not mean better efficiency.'),pair('30 bar a 6 L/min representan…','30 bar at 6 L/min represents…'),[pair('0,3 kW','0.3 kW'),pair('3 kW','3 kW'),pair('180 kW','180 kW')],0,pair('30 × 6 / 600 = 0,3 kW.','30 × 6 / 600 = 0.3 kW.'));
lesson('hydraulics','relief',pair('04 · Válvula de alivio','04 · Relief valve'),pair('Entender el retorno al tanque cuando la carga exige demasiada presión.','Understand tank return when load demands excessive pressure.'),pair('Una válvula de alivio ofrece una vía de presión a tanque al alcanzar su ajuste. Protege el circuito dentro de su capacidad; no garantiza que todas las cargas se muevan. Si todo el caudal se desvía a tanque, la potencia se disipa principalmente como calor. No es lo mismo una válvula de alivio que una reductora en una rama.','A relief valve provides a path from pressure to tank when its setting is reached. It protects the circuit within its capacity; it does not guarantee every load will move. If all flow bypasses to tank, power is mainly dissipated as heat. A relief valve is not the same as a pressure-reducing valve in a branch.'),'Q bomba / pump = Q actuador / actuator + Q retorno / return',pair('Una carga exige 80 bar pero el alivio limita a 60 bar. El cilindro no dispone de fuerza suficiente para esa carga. Con 6 L/min desviados y 60 bar, aproximadamente 600 W se convierten en calor.','A load requires 80 bar but relief limits pressure to 60 bar. The cylinder lacks sufficient force for that load. With 6 L/min bypassed at 60 bar, about 600 W becomes heat.'),pair('Usa la fuerza de la prensa como analogía: calcula la presión requerida antes de decidir si el actuador puede levantar una carga. Este banco no dibuja la válvula de alivio.','Use press force as an analogy: calculate required pressure before deciding whether the actuator can lift a load. This bench does not draw the relief valve.'),pair('No aumentes un ajuste real para ocultar un fallo: hay límites de componentes y carga.','Do not raise a real setting to hide a fault: component and load limits apply.'),pair('Con todo el caudal por alivio y cilindro quieto, la energía…','With all flow through relief and the cylinder stationary, energy…'),[pair('Desaparece','Disappears'),pair('Se convierte principalmente en calor','Mainly becomes heat'),pair('Se almacena indefinidamente','Is stored indefinitely')],1,pair('La caída de presión con caudal disipa potencia.','Pressure drop with flow dissipates power.'));
lesson('hydraulics','hydrodiagnosis',pair('05 · Cilindro lento: método de diagnóstico','05 · Slow cylinder: a diagnostic method'),pair('Separar falta de caudal, fuga y carga excesiva.','Distinguish low flow, leakage and excessive load.'),pair('Registra presión, caudal, temperatura y movimiento bajo la misma condición. Baja velocidad con presión normal puede indicar caudal insuficiente o fuga; presión alta sin avance puede indicar una carga excesiva o bloqueo. Ninguna pareja de lecturas identifica por sí sola un componente. Compara antes y después de una restricción y con una referencia conocida.','Record pressure, flow, temperature and movement under the same condition. Low speed at normal pressure may indicate insufficient flow or leakage; high pressure without movement may indicate excessive load or blockage. No pair of readings identifies a component by itself. Compare upstream and downstream of a restriction and against a known reference.'),'Q útil / useful = Q entrada / in − Q fuga / leak',pair('Entran 6 L/min y una fuga interna estimada desvía 2 L/min. Solo 4 L/min contribuyen al movimiento: para igual área, la velocidad es dos tercios de la ideal.','6 L/min enters and estimated internal leakage diverts 2 L/min. Only 4 L/min contributes to motion: for the same area, speed is two thirds of ideal.'),pair('Anota qué hipótesis explicarían un recorrido menor que el ideal de la prensa. Decide qué medición adicional distinguiría fuga de falta de suministro.','List hypotheses for less travel than the ideal press predicts. Decide which additional measurement distinguishes leakage from low supply.'),pair('Antes de intervenir, aislar energía, descargar presión y sostener cargas según procedimiento. No buscar fugas con la mano.','Before intervention, isolate energy, release pressure and support loads according to procedure. Do not search for leaks with your hand.'),pair('Para distinguir presión de caudal necesitas…','To distinguish pressure from flow you need…'),[pair('Solo escuchar la bomba','Only listen to the pump'),pair('Mediciones de ambas magnitudes bajo carga','Measurements of both quantities under load'),pair('Cambiar el cilindro','Replace the cylinder')],1,pair('Son magnitudes distintas: una lectura no sustituye la otra.','They are different quantities: one reading does not replace the other.'));
lesson('pneumatics','air',pair('01 · Aire y presión absoluta','01 · Air and absolute pressure'),pair('Distinguir presión manométrica, absoluta y compresibilidad.','Distinguish gauge pressure, absolute pressure and compressibility.'),pair('El aire almacena energía al comprimirse. La presión manométrica compara con el ambiente; la absoluta se mide desde el vacío. Las leyes de gases usan presión absoluta y temperatura absoluta. La relación pV constante requiere masa fija y temperatura aproximadamente constante; una compresión rápida puede calentar el aire.','Air stores energy when compressed. Gauge pressure compares with the surroundings; absolute pressure is measured from vacuum. Gas laws use absolute pressure and absolute temperature. Constant pV requires fixed mass and approximately constant temperature; rapid compression can heat the air.'),'p absoluta / absolute = p manométrica / gauge + p atm; p₁V₁ = p₂V₂',pair('Con atmósfera de 1 bar, 5 bar manométricos son 6 bar absolutos. Reducir a la mitad el volumen de una masa cerrada a temperatura constante eleva la presión absoluta a 12 bar, es decir 11 bar manométricos.','With 1 bar atmosphere, 5 bar gauge is 6 bar absolute. Halving a closed mass’s volume at constant temperature raises absolute pressure to 12 bar, or 11 bar gauge.'),pair('Identifica el depósito en el banco. Explica por qué puede conservar energía aunque el compresor esté desconectado.','Identify the receiver on the bench. Explain why it can retain energy even when the compressor is disconnected.'),pair('Usar presión manométrica en pV constante produce un resultado incorrecto.','Using gauge pressure in constant pV gives an incorrect result.'),pair('4 bar manométricos con atmósfera de 1 bar son…','4 bar gauge with 1 bar atmosphere is…'),[pair('3 bar absolutos','3 bar absolute'),pair('4 bar absolutos','4 bar absolute'),pair('5 bar absolutos','5 bar absolute')],2,pair('Se suma la presión atmosférica: 4 + 1 = 5.','Add atmospheric pressure: 4 + 1 = 5.'));
lesson('pneumatics','airchain',pair('02 · Preparación del aire','02 · Air preparation'),pair('Reconocer la función de cada elemento de suministro.','Recognise the function of each supply component.'),pair('El compresor aporta energía; el depósito amortigua demanda y almacena aire. Filtrado y secado reducen contaminación y humedad según la aplicación. El regulador ajusta presión aguas abajo dentro de su capacidad, pero necesita suministro suficiente. Un manómetro en reposo no demuestra que la presión se mantenga durante movimiento.','The compressor supplies energy; the receiver buffers demand and stores air. Filtration and drying reduce contamination and moisture for the application. A regulator adjusts downstream pressure within its capacity, but needs adequate supply. A stationary gauge reading does not prove pressure will hold during motion.'),'Δp circuito / circuit = p suministro / supply − p actuador / actuator',pair('Hay 6 bar en el depósito y 3 bar en el actuador al moverse. La diferencia puede incluir regulador, filtro, válvula y tuberías: hay que medir por tramos para localizar la pérdida.','The receiver has 6 bar and the moving actuator has 3 bar. The difference may include regulator, filter, valve and tubing: measure by sections to locate the loss.'),pair('Sigue compresor → regulador → puerto 1. Cambia presión y observa la fuerza calculada, no solo la posición animada.','Follow compressor → regulator → port 1. Change pressure and observe calculated force, not just animated position.'),pair('La lubricación de aire no es universal: depende de componentes y especificaciones.','Air lubrication is not universal: it depends on components and specifications.'),pair('Una presión correcta en reposo garantiza…','Correct pressure at rest guarantees…'),[pair('Caudal suficiente en movimiento','Enough flow during motion'),pair('Solo esa lectura en esa condición','Only that reading under that condition'),pair('Ausencia de fugas','No leaks')],1,pair('Debes observar también el sistema durante la demanda.','You must also observe the system during demand.'));
lesson('pneumatics','valve52',pair('03 · Válvula 5/2 y caminos del aire','03 · The 5/2 valve and air paths'),pair('Seguir suministro y escape en las dos posiciones.','Trace supply and exhaust in both positions.'),pair('5/2 significa cinco vías y dos posiciones. En este banco, 1 es alimentación, 2 y 4 van al cilindro, y 3 y 5 son escapes. Una posición conecta 1→2 y 4→5; la otra, 1→4 y 2→3. La cámara que no recibe suministro debe poder evacuar aire. Confirma siempre la numeración del símbolo concreto.','5/2 means five ports and two positions. On this bench, 1 is supply, 2 and 4 connect to the cylinder, and 3 and 5 are exhausts. One position connects 1→2 and 4→5; the other connects 1→4 and 2→3. The chamber not receiving supply must be able to exhaust. Always confirm the numbering on the actual symbol.'),'Avance / extend: 1→2, 4→5; retorno / retract: 1→4, 2→3',pair('Si el puerto 2 presuriza la cámara sin vástago, el pistón avanza y la cámara del vástago descarga por 4→5. Cambiar la posición invierte los caminos.','If port 2 pressurises the cap-end chamber, the piston extends while the rod-end chamber exhausts through 4→5. Switching position reverses the paths.'),pair('Pausa en avance y retorno. Localiza la corredera, los dos tubos de trabajo y el escape activo.','Pause during extension and retraction. Locate the spool, both working lines and the active exhaust.'),pair('Dos posiciones no significan dos velocidades ni dos niveles de presión.','Two positions does not mean two speeds or two pressure levels.'),pair('En 5/2, el número 5 indica…','In 5/2, the number 5 indicates…'),[pair('Puertos','Ports'),pair('Cilindros','Cylinders'),pair('Bares','Bars')],0,pair('La segunda cifra indica posiciones, la primera vías.','The second number means positions; the first means ports.'));
lesson('pneumatics','cylinderforce',pair('04 · Fuerza de avance y retorno','04 · Extension and retraction force'),pair('Calcular fuerzas considerando el área del vástago.','Calculate forces allowing for rod area.'),pair('La cámara sin vástago tiene el área completa del pistón; la otra tiene un área anular. A igual presión y escape a atmósfera, el retorno entrega menos fuerza teórica. En la realidad hay contrapresión, fricción y dinámica del aire: resta sus efectos para estimar fuerza disponible. El movimiento del banco está programado, no resuelve aceleración bajo carga.','The cap-end chamber has the full piston area; the other has an annular area. At equal pressure and atmospheric exhaust, retraction gives less theoretical force. Real back pressure, friction and air dynamics reduce available force. Bench motion is prescribed; it does not solve acceleration under load.'),'A = πD²/4; F avance / extend = pA; F retorno / retract = p(A − Arod)',pair('D = 40 mm, vástago = 20 mm, p = 4 bar: avance ≈ 503 N; retorno ≈ 377 N. Son fuerzas ideales con presión manométrica y escape atmosférico.','D = 40 mm, rod = 20 mm, p = 4 bar: extension ≈ 503 N; retraction ≈ 377 N. These are ideal forces using gauge pressure and atmospheric exhaust.'),pair('Compara la fuerza indicada en ambas posiciones a 4 bar. El banco conserva D = 40 mm y vástago = 20 mm.','Compare displayed force in both positions at 4 bar. The bench keeps D = 40 mm and rod = 20 mm.'),pair('No supongas igual fuerza en ambas direcciones de un cilindro de vástago simple.','Do not assume equal force in both directions of a single-rod cylinder.'),pair('Con igual presión, el retorno tiene menor fuerza porque…','At equal pressure, retraction force is lower because…'),[pair('El área efectiva es menor','Effective area is smaller'),pair('La presión desaparece','Pressure disappears'),pair('Siempre existe una fuga','There is always a leak')],0,pair('El vástago ocupa parte del área sobre la que actúa la presión.','The rod occupies part of the area on which pressure acts.'));
lesson('pneumatics','pneudiagnosis',pair('05 · Velocidad, atascos y evidencia','05 · Speed, sticking and evidence'),pair('Distinguir falta de aire, escape restringido y bloqueo mecánico.','Distinguish low air supply, restricted exhaust and mechanical binding.'),pair('La regulación de escape suele estabilizar la velocidad de cilindros de doble efecto, pero su efecto depende de carga y circuito. Si el pistón se detiene, comprueba presión durante demanda, posición de válvula, vías de escape y carga mecánica. Un sensor indica una condición detectada, no necesariamente movimiento completo ni causa del fallo.','Exhaust flow control often stabilises double-acting cylinder speed, but its effect depends on load and circuit. If the piston stops, check pressure during demand, valve position, exhaust paths and mechanical load. A sensor indicates a detected condition, not necessarily full travel or the fault cause.'),'F neta / net = pA·A − pB·(A − Arod) − F resistencia / resistance',pair('Un cilindro puede tener suministro correcto y moverse lentamente si el escape está restringido. Medir solo la presión de entrada no distingue esa condición de rozamiento o carga elevada.','A cylinder can have correct supply pressure yet move slowly if exhaust is restricted. Measuring inlet pressure alone cannot distinguish that condition from friction or high load.'),pair('Sigue el escape coloreado al cambiar de posición. Describe qué observaciones necesitarías para distinguir un silenciador obstruido de una guía mecánica trabada.','Follow the coloured exhaust as the valve switches. Describe observations needed to distinguish a clogged silencer from a binding mechanical guide.'),pair('Aislar y descargar aire almacenado antes de intervenir; asegurar cargas que puedan moverse al perder presión.','Isolate and release stored air before intervention; secure loads that could move when pressure is lost.'),pair('Antes de condenar la válvula, conviene comprobar…','Before condemning the valve, check…'),[pair('Suministro, mando, escape y carga','Supply, command, exhaust and load'),pair('Solo el sensor final','Only the end sensor'),pair('Solo el color del tubo','Only tube colour')],0,pair('Varias causas producen el mismo síntoma; la secuencia de pruebas debe separarlas.','Several causes produce the same symptom; the test sequence must distinguish them.'));
export const sources=[{name:'OpenStax · Physics / Física',url:'https://openstax.org/books/university-physics-volume-1/pages/14-3-pascals-principle-and-hydraulics'},{name:'Texas Instruments · Op amp limitations',url:'https://www.ti.com/lit/wp/sboa583/sboa583.pdf'},{name:'SMC · Cylinder flow control',url:'https://www.smcusa.com/help-and-support/best-practices/control-air-flow-of-cylinders'},{name:'DENSO · Starter troubleshooting',url:'https://www.denso-am.eu/news/starter-troubleshooting'}];
